此HTML的文档可以在Html:MathJaxC/doc创建
<script>
MathJax = {
tex: {
inlineMath: [['$', '$'], ['\\(', '\\)']],
tags:'ams',
useLabelIds: true,
},
chtml:{
scale:1
},
svg: {
fontCache: 'global'
},
startup: {
pageReady:function(){
return MathJax.startup.defaultPageReady().then(function(){
/*
这段代码允许我们使用以下方式来注册一个MathJax加载完毕后的回调函数
(window.MathJaxReadyCallback = window.MathJaxReadyCallback|| []).push(function)
*/
if(window.MathJaxReadyCallback){
for(var i=0;i<window.MathJaxReadyCallback.length;i++){
try{
window.MathJaxReadyCallback[i]();
}catch(e){console.error(e);}
}
}
window.MathJaxReadyCallback = {
push: function(f){
f();
}
};
});
}
}
};
</script>
<script src="https://huiji-fs.huijistatic.com/MathJax-3.2.1/es5/tex-mml-svg.js"></script>
