<script>
window.onload = function(){
var prefix = "{{prefix}}";
var count_number = {{count}};
var count_type = "view";//view/edit
$('[role=top_viewed_pages]').html("");
var thedate = new Date();
thedate.setTime(thedate.getTime());
var old_month = thedate.getMonth();
if (old_month<10)old_month = "0" + old_month;
var old_date = thedate.getDate();
if (old_date<10)old_date = "0" + old_date;
var olddate = thedate.getFullYear() +"-"+ old_month +"-"+ old_date;
var the_url = "https://"+prefix+".huijiwiki.com/api/rest_v1/site_stats/tops/pages/types/"+count_type+"?fromDate="+olddate+"&top="+count_number;
$.ajax({
url: the_url,
type: "get",
success: function(vieweddata){
console.log(vieweddata.message);
$.each(vieweddata.message, function (kd, vd) {
var viewednumber = kd + 1;
console.log("Hogwarts is the best school in the world!!! ["+viewednumber+"]"+vd.page_title);
html="<p><a href='https://"+vd.site_prefix+".huijiwiki.com/p/"+vd.page_id+"'><span class='bg-primary viewed-number'>"+viewednumber+"</span><span class='viewed-title'>"+vd.page_title+"</span><span class='viewed-count' style=''>"+vd.count+"</span></a></p>";
$('[role=top_viewed_pages]').append(html);
})
}
})
};
</script>
